class Solution {
    unordered_map<string,char>mymap2;
    unordered_map<char,string> mymap1;
public:
    bool wordPatternMatch(string pattern, string s) {

        if(pattern.size() == 0 && s.size() == 0)return true;
        else if(pattern.size() == 0 || s.size() == 0)return false;

        char p = pattern[0];
        pattern.erase(0,1);
        if(mymap1.find(p)!=mymap1.end()){
            string temp = mymap1[p];
            int pos = s.find(temp);
            if(pos!=0){
                return false;
            }
            s.erase(0,temp.size());
            if(wordPatternMatch(pattern,s))return true;
            else return false;

        }

        for(int i=1;i<=s.size();i++){// here i is not the index but
        // i is the length of the current substring which is going to be mapped
            string res = s.substr(0,i);//i is the length of the substring 
            if(mymap2.find(res)!=mymap2.end()){
                continue;
            }
            mymap2[res] = p;
            mymap1[p] = res;
            string s1 = s;
            s1.erase(0,i);
            if(wordPatternMatch(pattern,s1))return true;
            mymap1.erase(p);
            mymap2.erase(res);
        }
        return false;
    }
};

class Solution:
    def wordPatternMatch(self, pattern: str, s: str) -> bool:
        def dfs(i, j):
            if i == m and j == n:
                return True
            if i == m or j == n or n - j < m - i:
                return False
            for k in range(j, n):
                t = s[j : k + 1]
                if d.get(pattern[i]) == t:
                    if dfs(i + 1, k + 1):
                        return True
                if pattern[i] not in d and t not in vis:
                    d[pattern[i]] = t
                    vis.add(t)
                    if dfs(i + 1, k + 1):
                        return True
                    d.pop(pattern[i])
                    vis.remove(t)
            return False

        m, n = len(pattern), len(s)
        d = {}
        vis = set()
        return dfs(0, 0)

class Solution {
    private Set<String> vis;
    private Map<Character, String> d;
    private String p;
    private String s;
    private int m;
    private int n;

    public boolean wordPatternMatch(String pattern, String s) {
        vis = new HashSet<>();
        d = new HashMap<>();
        this.p = pattern;
        this.s = s;
        m = p.length();
        n = s.length();
        return dfs(0, 0);
    }

    private boolean dfs(int i, int j) {
        if (i == m && j == n) {
            return true;
        }
        if (i == m || j == n || m - i > n - j) {
            return false;
        }
        char c = p.charAt(i);
        for (int k = j + 1; k <= n; ++k) {
            String t = s.substring(j, k);
            if (d.getOrDefault(c, "").equals(t)) {
                if (dfs(i + 1, k)) {
                    return true;
                }
            }
            if (!d.containsKey(c) && !vis.contains(t)) {
                d.put(c, t);
                vis.add(t);
                if (dfs(i + 1, k)) {
                    return true;
                }
                vis.remove(t);
                d.remove(c);
            }
        }
        return false;
    }
}

class Solution {
public:
    bool wordPatternMatch(string pattern, string s) {
        unordered_set<string> vis;
        unordered_map<char, string> d;
        return dfs(0, 0, pattern, s, vis, d);
    }

    bool dfs(int i, int j, string& p, string& s, unordered_set<string>& vis, unordered_map<char, string>& d) {
        int m = p.size(), n = s.size();
        if (i == m && j == n) return true;
        if (i == m || j == n || m - i > n - j) return false;
        char c = p[i];
        for (int k = j + 1; k <= n; ++k) {
            string t = s.substr(j, k - j);
            if (d.count(c) && d[c] == t) {
                if (dfs(i + 1, k, p, s, vis, d)) return true;
            }
            if (!d.count(c) && !vis.count(t)) {
                d[c] = t;
                vis.insert(t);
                if (dfs(i + 1, k, p, s, vis, d)) return true;
                vis.erase(t);
                d.erase(c);
            }
        }
        return false;
    }
};

func wordPatternMatch(pattern string, s string) bool {
	m, n := len(pattern), len(s)
	vis := map[string]bool{}
	d := map[byte]string{}
	var dfs func(i, j int) bool
	dfs = func(i, j int) bool {
		if i == m && j == n {
			return true
		}
		if i == m || j == n || m-i > n-j {
			return false
		}
		c := pattern[i]
		for k := j + 1; k <= n; k++ {
			t := s[j:k]
			if v, ok := d[c]; ok && v == t {
				if dfs(i+1, k) {
					return true
				}
			}
			if _, ok := d[c]; !ok && !vis[t] {
				d[c] = t
				vis[t] = true
				if dfs(i+1, k) {
					return true
				}
				delete(d, c)
				vis[t] = false
			}
		}
		return false
	}
	return dfs(0, 0)
}

from collections import defaultdict
class Solution(object):
    def wordPatternMatch(self, pattern, str):
        """
        :type pattern: str
        :type str: str
        :rtype: bool
        """
        if not pattern:
            return not str
        if not str:
            return not pattern

        times = defaultdict(int)
        for c in pattern:
            times[c] += 1

        slen = len(str)
        times_list = times.items()
        combs = self.get_combinations(times_list, slen)

        for comb in combs:
            dct = {}
            idx = 0
            for c in pattern:
                if c not in dct:
                    dct[c]= str[idx:idx+comb[c]]
                else:
                    if dct[c]!=str[idx:idx+comb[c]]:
                        break
                idx += comb[c]
            else:
                if len(dct)!=len(set(dct.values())):
                    continue
                return True
        return False


    def get_combinations(self, times_list, slen):
        # times_list is like [(c, cnt), (c2, cnt2), ...]
        # returns: [{c1:3, c2:2}, {}, ...]
        if len(times_list)==1:
            key, cnt = times_list[0]
            if slen%cnt!=0:
                return []
            else:
                return [{key: slen/cnt}]
        i = 1
        results = []
        while True:
            key, cnt = times_list[0]
            if i*cnt>=slen:
                break
            sub_results = self.get_combinations(times_list[1:], slen-i*cnt)
            for d in sub_results:
                d.update({key: i})
                results.append(d)
            i += 1
        return results
